D.Quests[36085]={Title="展翼高飞",Description="现在轮到我们对信徒主动出击了。拉斯托克坚信他的新发明能让我们获得埃匹希斯武器的控制权，可我们必须靠近才行——而且要非常近。$B$B卡鲁和她的渡鸦们会送我们飞往啸风平台。在向晨曦平台推进前，我们先在那稳住脚跟吧。"}
D.Quests[36086]={Title=S[3849],Objectives=S[12055],Description="这花蕾证明了你有消灭木精的能力，你的角斗士朋友目击了你的战斗！把花蕾带回去给断肢，换取你应得的嘉奖！"}
D.Quests[36090]={Title=S[3844],Objectives=S[12056],Description="这根棘刺证明你拥有着消灭被感染者的力量，而你的斗士朋友亲眼见证了这一切！$b$b把棘刺交给乔纳领取嘉奖吧！"}
D.Quests[36091]={Title=S[3844],Objectives=S[12055],Description="这根棘刺证明你拥有着消灭被感染者的力量，而你的斗士朋友亲眼见证了这一切！$b$b把棘刺交给断肢领取嘉奖吧！"}
