D.Quests[37028]={Title=S[10475],Objectives="骑着你的训练中的啸狼去击败残爪。",Description="指挥官，我还有最后一项挑战要给你，这次可没那么简单。$B$B在德拉诺有一种狼，他们的皮肤像夜晚一样漆黑，他们体型比一般的狼要大上一倍，人们称他们为铁颚狼。它们转眼间就能把一个大活人撕成两半，任何脑子正常的动物遇到它们都会吓得腿软。$B$B有一头孤独的铁颚狼离开了它们世代居住的霜火岭跑到了纳格兰定居。骑上你的座狼去干掉它，如果你们两个能够生还，你的座狼才能成为一头真正的战兽。"}
D.Quests[37029]={Title="黑手之印",Objectives="在普通难度下，从黑石铸造厂每一区的最终首领身上获取4份山脉余烬、4份石之心和4份铁中银。",Description=S[106]}
D.Quests[37030]={Title="黑手之印（英雄）",Objectives="在英雄度下，从黑石铸造厂每一区的最终首领身上获取4份山脉余烬、4份石之心和4份铁中银。",Description=S[106]}
D.Quests[37031]={Title="黑手之印（史诗）",Objectives="在史诗难度下，从黑石铸造厂每一区的最终首领身上获取4份山脉余烬、4份石之心和4份铁中银。",Description=S[106]}
D.Quests[37032]={Title="野猪训练：裂鞭",Objectives=S[21796],Description="这头野猪的家乡就在戈尔隆德荒凉的平原上，我们训练起来会比较容易。和其它动物一样，我们先从它的家乡开始。$B$B让我瞧瞧你们两个能否干掉那头叫裂鞭的大迅猛龙，那家伙可是素来以捕食野猪闻名。"}
D.Quests[37033]={Title="野猪训练：格兹兰",Objectives=S[21793],Description=S[10791]}
D.Quests[37034]={Title="野猪训练：布巴波尔",Objectives=S[21790],Description=S[7561]}
D.Quests[37035]={Title="野猪训练：凶残的食人魔",Objectives="骑着你的训练中的石牙野猪去击败高里亚驱兽者。",Description=S[7391]}
D.Quests[37036]={Title="野猪训练：暗翼大鹏",Objectives=S[21791],Description=S[17849]}
